/**
 * The AURA wordmark's four letterforms, cut from the original logo at
 * logo/logo.jpeg (which is byte-identical to the logo the app already
 * displays). NOT a font and not a redrawn approximation: the glyph
 * geometry is the logo's own pixels.
 *
 * Extraction is reproducible: the wordmark is the only near-black
 * element in the logo (the illustration and the word "home" are
 * taupe), so a luminance threshold of 120 isolates rows 680-888,
 * and a column projection splits it at [(177, 355), (419, 588), (653, 809), (871, 1047)]. Each glyph is tinted
 * to --text-sidebar-muted (#b5a392), kept at its own
 * aspect ratio, and scaled to 116px tall.
 *
 * They ship as `data:` URIs on purpose. The renderer loads its own
 * images this way already (the profile-photo avatar), it is allowed by
 * the renderer CSP's `img-src ... data:`, and it resolves identically
 * in dev, in the production build and in the packaged Windows app —
 * unlike a path, which depends on how the window was loaded.
 */

export interface WordmarkGlyph {
  /** Stable key — the two A's differ, the logo mirrors their stroke weighting. */
  readonly key: string
  /** width / height of the glyph's own pixels, so a caller that sets only
   *  a height (a CSS mask has no intrinsic size) can never distort it. */
  readonly ratio: number
  readonly src: string
}

export const AURA_WORDMARK: readonly WordmarkGlyph[] = [
  { key: 'a1', ratio: 0.8534, src: 'data:image/png;base64,' },
  { key: 'u', ratio: 0.8103, src: 'data:image/png;base64,' },
  { key: 'r', ratio: 0.75, src: 'data:image/png;base64,' },
  { key: 'a2', ratio: 0.8448, src: 'data:image/png;base64,' },
]


/**
 * The "home" half of the same logo, cut from the same file. It is
 * genuinely lowercase and widely spaced in the original, and that is
 * what is reproduced here — not a font's uppercase HOME.
 *
 * These sit lower and lighter than the AURA wordmark (taupe, not
 * near-black), so they are isolated with a threshold of 120..253 over
 * rows 918-995 and split by column projection at
 * [(343, 390), (491, 543), (644, 723), (824, 874)]. Every glyph keeps
 * the FULL band height — only the horizontal crop is tight — so the
 * ascender on "h" and the x-height of "o/m/e" stay on a common
 * baseline when they are rendered side by side at one height.
 */
export const HOME_WORDMARK: readonly WordmarkGlyph[] = [
  { key: 'h', ratio: 0.6250, src: 'data:image/png;base64,' },
  { key: 'o', ratio: 0.6875, src: 'data:image/png;base64,' },
  { key: 'm', ratio: 1.0312, src: 'data:image/png;base64,' },
  { key: 'e', ratio: 0.6562, src: 'data:image/png;base64,' },
]
